  "implementation": "def solve(case):
    nodes = case.get('nodes')
    if not nodes:
        raise ValueError('Missing nodes')
    required_symbols = case.get('required_symbols')
    if not required_symbols:
        raise ValueError('Missing required_symbols')
    node_map = {}
    children_map = {}
    parent_map = {}
    for nd in nodes:
        nid = nd['id']
        node_map[nid] = nd
        parent = nd['parent']
        parent_map[nid] = parent
        if parent is not None:
            children_map.setdefault(parent, []).append(nid)
        else:
            children_map.setdefault(nid, [])
    root = [nid for nid in node_map if parent_map[nid] is None]
    if len(root) != 1:
        raise ValueError('Invalid tree: must have exactly one root')
    root_id = root[0]
    active = set(node_map.keys())
    removal_order = []
    # sort nodes: depth descending, id ascending (string compare)
    sorted_nodes = sorted(node_map.values(), key=lambda nd: (-nd['depth'], nd['id']))
    def count_symbols(exclude, keep_extra):
        counts = {}
        for nid in active:
            if nid == exclude:
                continue
            sym = node_map[nid]['symbol']
            counts[sym] = counts.get(sym, 0) + 1
        for nid in keep_extra:
            if nid == exclude:
                continue
            sym = node_map[nid]['symbol']
            counts[sym] = counts.get(sym, 0) + 1
        return counts
    def all_required_present(exclude, keep):
        counts = count_symbols(exclude, keep)
        for sym in required_symbols:
            if counts.get(sym, 0) == 0:
                return False
        return True
    for nd in sorted_nodes:
        nid = nd['id']
        if nid not in active:
            continue
        if not nd['removable'] or nid == root_id:
            continue
        # Deletion candidate
        active_children = [c for c in children_map.get(nid, []) if c in active]
        if len(active_children) == 0:
            if all_required_present(nid, []):
                active.remove(nid)
                removal_order.append(nid)
                continue
        # Replacement candidates: try each child in id order
        for child_id in sorted(active_children):
            # Replacement: remove nid, keep child, reattach child to nid's parent
            if all_required_present(nid, [child_id]):
                # Reattach child
                parent = parent_map[nid]
                # Update children of parent: replace nid with child_id
                if parent is not None:
                    p_children = children_map.get(parent, [])
                    for i, c in enumerate(p_children):
                        if c == nid:
                            p_children[i] = child_id
                            break
                    # Add child_id to parent's children if not already (should be there now)
                # Update parent of child
                parent_map[child_id] = parent
                # Remove nid from its own children (not needed)
                # Remove nid from active
                active.remove(nid)
                removal_order.append(nid)
                # The child remains active; its depth is effectively decreased but we don't track depth
                break  # Only one replacement per node
    retained_ids = sorted(active)
    return {'retained_ids': retained_ids, 'removal_order': removal_order}
